package ru.dvedev.me.yaphotoframe.cache

import java.io.File

/**
 * Как добираться до содержимого элемента.
 *
 * Разделение существует ради видео: семейный ролик с телефона осядет в кэше и
 * будет играть с диска, а шестигигабайтная съёмка с фотоаппарата не поместилась
 * бы никуда и пойдёт потоком. Для фотографий выбора нет — показывается
 * уменьшенная копия, и она всегда мала.
 */
sealed interface Delivery {

    /** Файл лежит на устройстве целиком. */
    data class Local(val file: File) : Delivery

    /**
     * Файл слишком велик для кэша и проигрывается по сети.
     *
     * Хранилище отдаёт частичное содержимое по запросу диапазона — проверено на
     * живом API, — поэтому качать целиком ради показа не требуется.
     */
    data class Streamed(
        val url: String,
        /** Под этим именем начало ролика лежит в буфере потока; null — без буфера. */
        val cacheKey: String? = null,
    ) : Delivery
}
